<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { CircleStop, FileCode2, FolderOpen, History, ListChecks, Network, Play, Plus, RefreshCw, Search, Settings, ShieldAlert } from '@lucide/vue'
import RunCenter from './RunCenter.vue'
import LiveLog from './LiveLog.vue'
import PlanManager from './PlanManager.vue'
import LogPage from './LogPage.vue'
import ScriptCard from './ScriptCard.vue'
import ScriptEditor from './ScriptEditor.vue'
import SettingsPage from './SettingsPage.vue'
import type { Config, LiveLogPhase, LiveSummaryLog, MaaEndAdapter, MAAAdapter, Preset, Queue, RunItem, Runtime, ScriptLogSource, ScriptReadableEvent, Task } from './types'
import { useRunnerConnection } from './useRunnerConnection'
import { liveLogLabel } from './logLabels'

type HistoryRun = { id: string; queue_name: string; run_mode?: string; trigger_source: string; state: string; started_at: string; items: RunItem[]; scheduler_skips?: string[] }
type DeferredPreset = { presetId: string; path: string }
type Page = 'scripts' | 'editor' | 'schedule' | 'history' | 'history-detail' | 'settings'
type ScriptExecution = { kind: 'idle' | 'queued' | 'running' | 'waiting_manual' | 'closing' | 'cooling_down' | 'succeeded' | 'failed' | 'stopped'; label: string; detail?: string }
type LiveLogEntry = LiveSummaryLog
type EditorDraft = { script: Queue; task: Task; isNew: boolean }
type HistoryDetailState = { runId: string; taskId: string; taskListScrollTop: number }
type AppSettings = { autoStart: boolean; minimizeOnLaunch: boolean; notifications: { completed: boolean; failed: boolean; system: boolean } }

const config = ref<Config>({ schema_version: 3, queues: [], tasks: [], plans: [], fired_slots: [], startup_fired_dates: {} })
const runtime = ref<Runtime>({ busy: false, activeTaskId: null, cooldownSeconds: 0, cooldownUntil: null, runCenter: null, run: null })
const presets = ref<Preset[]>([]); const history = ref<HistoryRun[]>([]); const logs = ref<LiveLogEntry[]>([])
const scriptLogs = ref<ScriptLogSource[]>([])
const scriptEvents = ref<ScriptReadableEvent[]>([])
const saveError = ref(''); const page = ref<Page>('scripts'); const query = ref(''); const notice = ref('正在确认本地后端…'); const migrationNotice = ref('')
const editingScriptId = ref<string | null>(null); const editorDraft = ref<EditorDraft | null>(null); const editorDirty = ref(false); const editorSaveState = ref<'saved' | 'saving' | 'draft' | 'failed'>('saved'); const leaveEditor = ref(false); const leaveDestination = ref<Page>('scripts'); const selectedPlanId = ref<string | null>(null); const selectedHistoryRunId = ref<string | null>(null); const historyDetail = ref<HistoryDetailState | null>(null); const historyReturnState = ref<HistoryDetailState | null>(null)
const expandedHistory = ref(new Set<string>()); const draggedScript = ref<string | null>(null); const allRunProblems = ref<string[]>([])
const selectionIssues = ref<Record<string, string>>({}); const deferredPresets = ref<Record<string, DeferredPreset>>({}); const presetRequestSerial = new Map<string, number>()
const confirmationPending = ref(false); const updatePending = ref(false); const countdownNow = ref(Date.now()); const saveState = ref<'saved' | 'saving' | 'draft' | 'failed'>('saved')
const appSettings = ref<AppSettings>({ autoStart: false, minimizeOnLaunch: false, notifications: { completed: true, failed: true, system: true } }); const settingsSaveState = ref<'idle' | 'saving' | 'saved' | 'failed'>('idle')
const appVersion = ref('开发版本读取中'); const backendDetail = ref(''); let localRevision = 0; let savedRevision = 0; let saveFlight: Promise<void> | undefined; let historyFlight: Promise<void> | undefined; let terminalHistoryId: string | null = null; let countdownTimer: number | undefined; let exitAppRunId: string | null = null; let summaryRunId: string | null = null; let summarySequence = 0; let summaryResyncing = false; let scriptRunId: string | null = null; let scriptResyncing = false; let scriptEventRunId: string | null = null; let scriptEventSequence = 0
let terminalNotificationRunId: string | null = null
const taskBook = computed(() => new Map(config.value.tasks.map((task) => [task.id, task])))
const editingScript = computed(() => editorDraft.value?.script || null)
const editingTask = computed(() => editorDraft.value?.task || null)
const hours = Array.from({ length: 24 }, (_, index) => String(index).padStart(2, '0'))
const minutes = Array.from({ length: 60 }, (_, index) => String(index).padStart(2, '0'))
const visibleScripts = computed(() => { const text = query.value.trim().toLocaleLowerCase(); return !text ? config.value.queues : config.value.queues.filter((script) => `${script.name} ${scriptTask(script)?.name || ''} ${presetSummary(script)}`.toLocaleLowerCase().includes(text)) })
const hasUnsavedDraft = computed(() => editorDirty.value || localRevision > savedRevision)
const isMaa = computed(() => editingTask.value?.preset_id === 'maa'); const isMaaEnd = computed(() => editingTask.value?.preset_id === 'maaend')
const editorSaveLabel = computed(() => runtime.value.busy ? '本轮运行中，配置已锁定' : editorSaveState.value === 'saving' ? '保存中…' : editorSaveState.value === 'failed' ? '保存失败，请重试' : editorDirty.value ? '有未保存更改' : '已保存')
const cooldown = computed(() => { const until = runtime.value.cooldownUntil; if (!until) return runtime.value.cooldownSeconds || 0; countdownNow.value; return Math.max(0, Math.ceil((new Date(until).getTime() - Date.now()) / 1000)) })
const connection = useRunnerConnection(refresh, handleRealtime)
const connectionSummary = computed(() => connection.restOnline.value ? (connection.realtimeState.value === 'online' ? '本地后端与实时状态已连接' : '实时状态正在恢复') : '本地后端不可用')
const diagnosticText = computed(() => JSON.stringify({ API: connection.restOnline.value ? '在线' : '离线', 实时状态: connection.realtimeLabel.value, 主进程: backendDetail.value || '无' }, null, 2))

function uid() { return crypto.randomUUID() }
function copy<T>(value: T): T { return JSON.parse(JSON.stringify(value)) as T }
function normalizeConfig(raw: Config) { raw.plans.forEach((plan) => { plan.script_ids = plan.items.map((item) => item.script_id); plan.run_on_startup = plan.startup_mode !== 'never' }); return raw }
function directoryOf(path: string) { return path.replace(/[\\/][^\\/]+$/, '') }
function fileName(path: string) { return path.replace(/^.*[\\/]/, '').toLocaleLowerCase() }
function scriptTasks(script: Queue) { return script.task_ids.map((id) => taskBook.value.get(id)).filter(Boolean) as Task[] }
function scriptTask(script: Queue) { return scriptTasks(script)[0] || null }
function draft(): Task { return { id: uid(), name: '新程序', executable: '', arguments: [], working_directory: null, allow_manual_confirmation: true, allow_process_exit: true, log_path: null, log_idle_timeout_seconds: null, success_log: null, success_log_mode: 'keyword', failure_log: null, failure_log_mode: 'keyword', success_log_rules: [], failure_log_rules: [], preset_id: null, preset_evidence: null, timeout_seconds: 600, maa_adapter: null, maaend_adapter: null } }
function presetFor(task: Task) { return presets.value.find((preset) => preset.id === task.preset_id) }
function presetLabel(task: Task | null) { return task ? (presetFor(task)?.label || '通用程序') : '通用程序' }
function presetSummary(script: Queue) { return presetLabel(scriptTask(script)) }
function matchesPreset(task: Task, executable = task.executable) { const preset = presetFor(task); return !task.preset_id || !!preset?.executables.some((name) => name.toLocaleLowerCase() === fileName(executable)) }
function presetRuleText(task: Task, type: 'success' | 'failure') { const storedRules = type === 'success' ? task.success_log_rules : task.failure_log_rules; const presetRules = type === 'success' ? presetFor(task)?.successRules : presetFor(task)?.failureRules; const rules = storedRules.length ? storedRules : (presetRules || []); return rules.map((rule) => `${rule.mode === 'regex' ? '正则' : '关键字'}：${rule.pattern}`).join('；') || '无（由人工确认完成）' }
function friendlyError(error: unknown) {
  const raw = error instanceof Error ? error.message : String(error)
  try {
    const payload = JSON.parse(raw) as { detail?: unknown }
    const detail = payload.detail
    if (Array.isArray(detail) && detail.some((item) => Array.isArray((item as { loc?: unknown }).loc) && ((item as { loc: unknown[] }).loc.includes('days')))) return '请至少选择一个运行日后再保存。'
    if (typeof detail === 'string') return detail
  } catch { /* 保留可读的普通后端错误 */ }
  return raw.includes('days') || raw.includes('min_length') ? '请至少选择一个运行日后再保存。' : raw
}
function report(title: string, error: unknown) { notice.value = `${title}：${friendlyError(error)}` }
function taskProblem(task: Task): string | null { if (!task.executable.trim()) return '未选择程序路径'; if (task.preset_id && !matchesPreset(task)) return '预设路径不匹配'; if (task.preset_id && !task.preset_evidence) return '预设规则尚未应用'; return null }
function scriptProblems(script: Queue) { const task = scriptTask(script); return !task ? [`软件脚本“${script.name}”缺少程序`] : taskProblem(task) ? [`软件脚本“${script.name}”：${taskProblem(task)}`] : [] }
function scriptBlocked(script: Queue) { return scriptProblems(script).length > 0 }
function itemReason(item: RunItem) { return item.error_summary || (item.exit_code !== null && item.exit_code !== undefined ? `退出码 ${item.exit_code}` : item.completion_source || '未提供摘要') }
function executionFor(script: Queue): ScriptExecution { const item = runtime.value.run?.items.find((candidate) => candidate.script_id === script.id || candidate.task_id === scriptTask(script)?.id); if (!item) return { kind: 'idle', label: '' }; if (item.state === 'queued') return { kind: 'queued', label: '等待运行' }; if (['validating', 'starting', 'monitoring'].includes(item.state)) return { kind: 'running', label: '运行中' }; if (item.state === 'waiting_manual') return { kind: 'waiting_manual', label: '等待确认' }; if (item.state === 'waiting_update') return { kind: 'waiting_manual', label: '需要处理' }; if (['closing', 'force_closing'].includes(item.state)) return { kind: 'closing', label: '正在收尾' }; if (item.state === 'cooling_down') return { kind: 'cooling_down', label: '冷却中' }; if (item.state === 'succeeded') return { kind: 'succeeded', label: '已完成', detail: item.completion_source || undefined }; if (item.state === 'failed') return { kind: 'failed', label: '失败', detail: itemReason(item) }; return { kind: 'stopped', label: '已停止' } }

async function refreshHistory(focus?: string) { if (!connection.restOnline.value || historyFlight) return historyFlight; historyFlight = (async () => { const data = await connection.request('/api/history') as { runs: HistoryRun[] }; history.value = data.runs; if (focus) { selectedHistoryRunId.value = focus; expandedHistory.value = new Set([...expandedHistory.value, focus]) } })().catch((error) => report('无法刷新运行历史', error)).finally(() => { historyFlight = undefined }); return historyFlight }
async function refresh() { const remote = normalizeConfig(await connection.request('/api/config') as Config); remote.plans ||= []; if (!hasUnsavedDraft.value) config.value = remote; selectedPlanId.value ??= config.value.plans[0]?.id || null; applyRuntime(await connection.request('/api/runtime') as Runtime); migrationNotice.value = runtime.value.migrationNotice || ''; presets.value = await connection.request('/api/presets') as Preset[]; await refreshHistory(); await reconcileLoadedPresets(); if (localRevision > savedRevision) await flushSave(); if (migrationNotice.value) notice.value = migrationNotice.value }
function logPhase(message: string): LiveLogPhase { const state = runtime.value.run?.items.find((item) => item.task_id === runtime.value.activeTaskId)?.state; if (state === 'validating' || /校验/.test(message)) return 'validation'; if (state === 'waiting_manual' || /等待人工确认/.test(message)) return 'waiting'; if (state === 'closing' || state === 'force_closing' || /收尾|关闭/.test(message)) return 'closing'; if (state === 'cooling_down' || /冷却/.test(message)) return 'cooling'; if (state === 'failed' || runtime.value.run?.state === 'stopped' || /失败|非零退出|停止|取消/.test(message)) return 'failed'; if (state === 'succeeded' || /成功|全部成功/.test(message)) return 'success'; if (state === 'starting' || state === 'monitoring' || /启动|运行/.test(message)) return 'running'; return 'info' }
function livePhase(value: unknown, message: string): LiveLogPhase { return ['validation', 'running', 'waiting', 'closing', 'cooling', 'success', 'failed', 'info'].includes(String(value)) ? value as LiveLogPhase : logPhase(message) }
function makeLiveEntry(data: LiveSummaryLog): LiveLogEntry { const name = runtime.value.run?.items.find((item) => item.task_id === data.taskId)?.task_name || config.value.tasks.find((task) => task.id === data.taskId)?.name; return { ...data, message: liveLogLabel(data.message, name), phase: livePhase(data.phase, data.message) } }
function hydrateLiveLogs(next: Runtime) { const runId = next.run?.id || null; if (!runId) { logs.value = []; summaryRunId = null; summarySequence = 0; return } if (!Array.isArray(next.liveLogs)) { if (summaryRunId !== runId) { logs.value = []; summaryRunId = runId; summarySequence = 0 }; return } const merged = new Map<number, LiveLogEntry>(); if (summaryRunId === runId) for (const item of logs.value) merged.set(item.sequence, item); for (const item of next.liveLogs) if (item.runId === runId && Number.isInteger(item.sequence) && item.sequence > 0 && typeof item.message === 'string') merged.set(item.sequence, makeLiveEntry(item)); const ordered = [...merged.values()].sort((left, right) => left.sequence - right.sequence).slice(-40); logs.value = ordered; summaryRunId = runId; summarySequence = ordered.length ? ordered[ordered.length - 1].sequence : 0 }
function scriptLogKey(item: Pick<ScriptLogSource, 'taskId' | 'sourceId'>) { return `${item.taskId}:${item.sourceId}` }
function hydrateScriptLogs(next: Runtime) { const runId = next.run?.id || null; if (!runId) { scriptLogs.value = []; scriptRunId = null; return } if (!Array.isArray(next.scriptLogs)) { if (scriptRunId !== runId) { scriptLogs.value = []; scriptRunId = runId }; return } const sources = new Map<string, ScriptLogSource>(); for (const item of next.scriptLogs) if (item.runId === runId && item.taskId && item.sourceId && Number.isInteger(item.sequence) && item.sequence >= 0 && typeof item.text === 'string') sources.set(scriptLogKey(item), { ...item, append: false }); scriptLogs.value = [...sources.values()].sort((left, right) => right.updatedAt.localeCompare(left.updatedAt)); scriptRunId = runId }
function hydrateScriptEvents(next: Runtime) { const runId = next.run?.id || null; if (!runId) { scriptEvents.value = []; scriptEventRunId = null; scriptEventSequence = 0; return } if (!Array.isArray(next.scriptEvents)) { if (scriptEventRunId !== runId) { scriptEvents.value = []; scriptEventRunId = runId; scriptEventSequence = 0 }; return } const merged = new Map<number, ScriptReadableEvent>(); if (scriptEventRunId === runId) for (const item of scriptEvents.value) merged.set(item.sequence, item); for (const item of next.scriptEvents) if (item.runId === runId && Number.isInteger(item.sequence) && item.sequence > 0 && item.event?.source === 'script') merged.set(item.sequence, item); const ordered = [...merged.values()].sort((left, right) => left.sequence - right.sequence).slice(-240); scriptEvents.value = ordered; scriptEventRunId = runId; scriptEventSequence = ordered.at(-1)?.sequence || 0 }
function applyRuntime(next: Runtime) { runtime.value = next; hydrateLiveLogs(next); hydrateScriptLogs(next); hydrateScriptEvents(next); notifyRunTerminal(next) }
function notifyRunTerminal(next: Runtime) {
  const run = next.run
  if (!run || terminalNotificationRunId === run.id || !['completed', 'failed', 'stopped'].includes(run.state)) return
  terminalNotificationRunId = run.id
  const failed = run.state !== 'completed' || run.items.some((item) => item.state === 'failed')
  const kind = failed ? 'failed' : 'completed'
  const title = failed ? '顺序任务调度器：本轮未完全成功' : '顺序任务调度器：本轮已完成'
  const body = failed ? `${run.queue_name} 已结束，请查看运行中心或日志。` : `${run.queue_name} 已按顺序完成。`
  void window.desktopRunner?.showNotification?.({ kind, title, body }).then((result) => { if (result.webhookFailures || result.qqFailed) notice.value = '部分通知发送失败，请在通知设置中检查。' }).catch(() => { notice.value = '通知发送失败，请在通知设置中检查。' })
}
async function resyncLiveLogs() { if (summaryResyncing) return; summaryResyncing = true; try { applyRuntime(await connection.request('/api/runtime') as Runtime) } catch (error) { report('无法重同步本轮日志摘要', error) } finally { summaryResyncing = false } }
function appendLiveLog(data: Partial<LiveSummaryLog>) { const sequence = data.sequence; if (!data.runId || sequence === undefined || !Number.isInteger(sequence) || !data.message) { const message = data.message || ''; logs.value = [...logs.value.slice(-39), { runId: runtime.value.run?.id || 'legacy', sequence: summarySequence + 1, taskId: data.taskId, message: liveLogLabel(message), phase: logPhase(message) }]; summarySequence += 1; return } if (data.runId !== runtime.value.run?.id) return; if (summaryRunId !== data.runId || sequence !== summarySequence + 1) { if (sequence <= summarySequence) return; void resyncLiveLogs(); return } const next = makeLiveEntry(data as LiveSummaryLog); logs.value = [...logs.value.slice(-39), next]; summarySequence = next.sequence }
async function resyncScriptLogs() { if (scriptResyncing) return; scriptResyncing = true; try { applyRuntime(await connection.request('/api/runtime') as Runtime) } catch (error) { report('无法重同步脚本日志', error) } finally { scriptResyncing = false } }
function appendScriptLog(data: Partial<ScriptLogSource> & { runId?: string; taskId?: string; text?: string }) { const runId = data.runId; const taskId = data.taskId; if (!runId || !taskId || runId !== runtime.value.run?.id || typeof data.text !== 'string') return; const sourceId = data.sourceId || 'legacy'; const key = `${taskId}:${sourceId}`; const index = scriptLogs.value.findIndex((item) => scriptLogKey(item) === key); const old = index >= 0 ? scriptLogs.value[index] : undefined; const sequence = data.sequence; if (typeof sequence !== 'number' || !Number.isInteger(sequence)) { const legacy: ScriptLogSource = { runId, taskId, sourceId, sourceName: data.sourceName || '脚本日志', sourceType: data.sourceType || 'external', sequence: (old?.sequence || 0) + 1, append: true, text: (old?.text || '') + data.text, truncated: Boolean(old?.truncated), updatedAt: data.updatedAt || new Date().toISOString() }; scriptLogs.value = [...scriptLogs.value.filter((item) => scriptLogKey(item) !== key), legacy]; return } if (old && sequence <= old.sequence) return; if (data.append && (!old || sequence !== old.sequence + 1)) { void resyncScriptLogs(); return } const next: ScriptLogSource = { runId, taskId, sourceId, sourceName: data.sourceName || old?.sourceName || '脚本日志', sourceType: data.sourceType || old?.sourceType || 'external', sequence, append: Boolean(data.append), text: data.append ? (old?.text || '') + data.text : data.text, truncated: Boolean(data.truncated), updatedAt: data.updatedAt || new Date().toISOString() }; scriptLogs.value = [...scriptLogs.value.filter((item) => scriptLogKey(item) !== key), next].sort((left, right) => right.updatedAt.localeCompare(left.updatedAt)); scriptRunId = runId }
function appendScriptEvent(data: Partial<ScriptReadableEvent>) { const sequence = data.sequence; if (!data.runId || data.runId !== runtime.value.run?.id || !data.taskId || !data.event || data.event.source !== 'script' || typeof sequence !== 'number' || !Number.isInteger(sequence)) return; const next = data as ScriptReadableEvent; if (scriptEventRunId === data.runId && data.replace) { const index = scriptEvents.value.findIndex((entry) => entry.sequence === sequence); if (index < 0) { void resyncScriptLogs(); return } const merged = [...scriptEvents.value]; merged[index] = next; scriptEvents.value = merged; return } if (scriptEventRunId !== data.runId || sequence !== scriptEventSequence + 1) { if (sequence <= scriptEventSequence) return; void resyncScriptLogs(); return } scriptEvents.value = [...scriptEvents.value.slice(-239), next]; scriptEventRunId = next.runId; scriptEventSequence = next.sequence }
function handleRuntime(next: Runtime) { applyRuntime(next); const completion = runtime.value.completionAction; if (completion?.action === 'exit_app' && completion.status === 'executing' && exitAppRunId !== completion.runId) { exitAppRunId = completion.runId; void window.desktopRunner?.quitApp?.() } if (confirmationPending.value && runtime.value.runCenter?.currentState !== 'waiting_manual') confirmationPending.value = false; const finished = runtime.value.run && ['completed', 'stopped'].includes(runtime.value.run.state); if (finished && runtime.value.run!.id !== terminalHistoryId) { terminalHistoryId = runtime.value.run!.id; void refreshHistory(runtime.value.run!.id); notice.value = runtime.value.run!.state === 'stopped' ? '本轮已停止，不会启动下一项。' : runtime.value.run!.items.some((item) => item.state === 'failed') ? '整轮执行完成，存在失败项。' : '整轮执行完成。' } }
function handleRealtime(event: { type: string; data: unknown }) { if (event.type === 'runtime') handleRuntime(event.data as Runtime); if (event.type === 'config' && !hasUnsavedDraft.value) config.value = normalizeConfig(event.data as Config); if (event.type === 'schedule') notice.value = (event.data as { message: string }).message; if (event.type === 'log') appendLiveLog(event.data as Partial<LiveSummaryLog>); if (event.type === 'script_log') appendScriptLog(event.data as Partial<ScriptLogSource>); if (event.type === 'script_event') appendScriptEvent(event.data as Partial<ScriptReadableEvent>)
}
async function flushSave() {
  if (saveFlight) return saveFlight
  saveFlight = (async () => {
    if (savedRevision < localRevision) saveState.value = 'saving'
    while (connection.restOnline.value && savedRevision < localRevision) {
      const revision = localRevision
      const snapshot = JSON.parse(JSON.stringify(config.value)) as Config
      try {
        const accepted = await connection.request('/api/config', { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify(snapshot) }) as Config
        accepted.plans ||= []
        savedRevision = revision
        if (revision === localRevision) config.value = normalizeConfig(accepted)
      } catch (error) {
        if (revision !== localRevision) continue
        saveState.value = 'failed'
        saveError.value = `保存失败，草稿将保留：${friendlyError(error)}`
        break
      }
    }
    if (savedRevision === localRevision && connection.restOnline.value) { saveState.value = 'saved'; saveError.value = '' }
    else if (!connection.restOnline.value && savedRevision < localRevision) { saveState.value = 'draft'; saveError.value = '本地后端不可用，草稿将保留。' }
  })().finally(() => { saveFlight = undefined })
  return saveFlight
}
function save() { if (page.value === 'editor' && editorDraft.value) { editorDirty.value = true; editorSaveState.value = 'draft'; return Promise.resolve() } localRevision += 1; if (!connection.restOnline.value) { saveState.value = 'draft'; saveError.value = '本地后端不可用，草稿将保留。'; return Promise.resolve() } return flushSave() }
function finishCloseEditor(destination: Page = 'scripts') { editorDraft.value = null; editorDirty.value = false; editorSaveState.value = 'saved'; leaveEditor.value = false; editingScriptId.value = null; page.value = destination }
function requestLeaveEditor(destination: Page = 'scripts') { if (!editorDirty.value) return finishCloseEditor(destination); leaveDestination.value = destination; leaveEditor.value = true }
function navigate(destination: Exclude<Page, 'editor' | 'history-detail'>) { if (page.value === 'editor') requestLeaveEditor(destination); else { if (destination === 'history') historyDetail.value = null; page.value = destination } }
async function saveEditorChanges() {
  const draftState = editorDraft.value
  if (!draftState || runtime.value.busy) return false
  if (!connection.restOnline.value) { editorSaveState.value = 'failed'; saveError.value = '本地后端不可用，草稿将保留。'; return false }
  editorSaveState.value = 'saving'; saveError.value = ''
  const snapshot = copy(config.value)
  const taskIndex = snapshot.tasks.findIndex((task) => task.id === draftState.task.id)
  const scriptIndex = snapshot.queues.findIndex((script) => script.id === draftState.script.id)
  if (taskIndex >= 0) snapshot.tasks[taskIndex] = copy(draftState.task); else snapshot.tasks.push(copy(draftState.task))
  if (scriptIndex >= 0) snapshot.queues[scriptIndex] = copy(draftState.script); else snapshot.queues.push(copy(draftState.script))
  try {
    const accepted = normalizeConfig(await connection.request('/api/config', { method: 'PUT', headers: { 'content-type': 'application/json' }, body: JSON.stringify(snapshot) }) as Config)
    config.value = accepted
    const acceptedScript = accepted.queues.find((script) => script.id === draftState.script.id)
    const acceptedTask = accepted.tasks.find((task) => task.id === draftState.task.id)
    if (acceptedScript && acceptedTask) editorDraft.value = { script: copy(acceptedScript), task: copy(acceptedTask), isNew: false }
    editorDirty.value = false; editorSaveState.value = 'saved'; notice.value = '保存成功。'
    if (leaveEditor.value) finishCloseEditor(leaveDestination.value)
    return true
  } catch (error) { editorSaveState.value = 'failed'; saveError.value = `保存失败，草稿将保留：${friendlyError(error)}`; return false }
}
function openEditor(script: Queue) { const task = scriptTask(script); if (!task) return; editingScriptId.value = script.id; editorDraft.value = { script: copy(script), task: copy(task), isNew: false }; editorDirty.value = false; editorSaveState.value = 'saved'; page.value = 'editor' }
function closeEditor() { requestLeaveEditor('scripts') }
function newScript() { const task = draft(); const script: Queue = { id: uid(), name: task.name, task_ids: [task.id], time_slots: [] }; editingScriptId.value = script.id; editorDraft.value = { script, task, isNew: true }; editorDirty.value = false; editorSaveState.value = 'saved'; page.value = 'editor' }
function duplicateScript(script: Queue) { const task = scriptTask(script); if (!task) return; const cloned = copy(task); cloned.id = uid(); cloned.name += ' 副本'; const clone: Queue = { id: uid(), name: cloned.name, task_ids: [cloned.id], time_slots: [] }; config.value.tasks.push(cloned); config.value.queues.push(clone); void save() }
function deleteScript(script: Queue) { if (runtime.value.busy) return; const existed = config.value.queues.some((item) => item.id === script.id); const ids = new Set(script.task_ids); config.value.queues = config.value.queues.filter((item) => item.id !== script.id); config.value.tasks = config.value.tasks.filter((task) => !ids.has(task.id)); config.value.plans = config.value.plans.map((plan) => ({ ...plan, items: plan.items.filter((item) => item.script_id !== script.id) })); if (editingScriptId.value === script.id) finishCloseEditor(); if (existed) void save() }
function moveScript(targetId: string) { if (!draggedScript.value || draggedScript.value === targetId) return; const from = config.value.queues.findIndex((script) => script.id === draggedScript.value); const to = config.value.queues.findIndex((script) => script.id === targetId); if (from < 0 || to < 0) return; const [moved] = config.value.queues.splice(from, 1); config.value.queues.splice(to, 0, moved); void save() }
function clearAppliedRules(task: Task) { task.preset_evidence = null; task.log_path = null; task.success_log_rules = []; task.failure_log_rules = []; task.allow_manual_confirmation = true; task.allow_process_exit = false }
function scriptForEditorTask(task: Task) { return editorDraft.value?.task.id === task.id ? editorDraft.value.script : config.value.queues.find((item) => item.task_ids[0] === task.id) }
async function applyPreset(task: Task, path: string, serial: number) { const presetId = task.preset_id; if (!presetId) return; const oldRegion = task.ui_log_region?.executable.toLocaleLowerCase() === path.toLocaleLowerCase() ? task.ui_log_region : null; const oldMaaEnd = task.maaend_adapter ? { game_executable: task.maaend_adapter.game_executable, game_arguments: [...task.maaend_adapter.game_arguments], game_wait_seconds: task.maaend_adapter.game_wait_seconds, close_game_on_finish: task.maaend_adapter.close_game_on_finish } : null; const applied = await connection.request(`/api/presets/${presetId}/apply`, { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ executable: path, task_id: task.id, name: task.name === '新程序' ? '' : task.name }) }) as Task; if (presetRequestSerial.get(task.id) !== serial || task.executable !== path) return; Object.assign(task, applied); if (oldRegion) task.ui_log_region = oldRegion; if (presetId === 'maaend' && oldMaaEnd && task.maaend_adapter) Object.assign(task.maaend_adapter, oldMaaEnd, { installation_directory: directoryOf(path) }); const script = scriptForEditorTask(task); if (script && script.name === '新程序') script.name = task.name; delete selectionIssues.value[task.id]; await save() }
async function synchronizeExecutable(task: Task, raw: string) { const path = raw.trim(); const serial = (presetRequestSerial.get(task.id) || 0) + 1; presetRequestSerial.set(task.id, serial); task.executable = path; task.working_directory = path ? directoryOf(path) : null; if (!task.preset_id || !path) return save(); clearAppliedRules(task); if (!matchesPreset(task, path)) { selectionIssues.value = { ...selectionIssues.value, [task.id]: `已保留路径，但该 EXE 不符合 ${presetLabel(task)} 模板。请重新选择或切换通用程序。` }; return save() } try { await applyPreset(task, path, serial) } catch (error) { selectionIssues.value = { ...selectionIssues.value, [task.id]: '预设规则未能应用；路径已保留。' }; await save(); report('无法应用预设规则', error) } }
function changePreset(task: Task, event: Event) { task.preset_id = (event.target as HTMLSelectElement).value || null; selectPreset(task) }
function selectPreset(task: Task) { if (!task.preset_id) { task.preset_evidence = null; task.maa_adapter = null; task.maaend_adapter = null; void save(); return } const preset = presetFor(task); if (task.name === '新程序' && preset) { task.name = preset.label; const script = scriptForEditorTask(task); if (script && script.name === '新程序') script.name = preset.label } if (task.preset_id === 'maa') task.maa_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, adb_executable: null, adb_address: null, last_check_at: null, last_check_ok: null, last_check_message: null }; if (task.preset_id === 'maaend') task.maaend_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, game_executable: null, game_arguments: [], game_wait_seconds: 60, close_game_on_finish: true }; if (task.executable) void synchronizeExecutable(task, task.executable); else void save() }
async function reconcileLoadedPresets() { if (runtime.value.busy || !connection.restOnline.value || hasUnsavedDraft.value) return; for (const task of config.value.tasks) { if (task.preset_id && task.executable && (!task.preset_evidence || (presetFor(task)?.requiresLogRules && (!task.success_log_rules.length || !task.failure_log_rules.length)))) await synchronizeExecutable(task, task.executable) } }
async function choose(task: Task) { const result = await window.desktopRunner?.selectExecutable(task.preset_id); if (result?.path) await synchronizeExecutable(task, result.path) }
async function chooseInstallDirectory(task: Task, executable: 'MAA.exe' | 'MaaEnd.exe') { const result = await window.desktopRunner?.selectDirectory?.(); if (!result?.path) return; await synchronizeExecutable(task, `${result.path}\\${executable}`) }
function updateInstallDirectory(task: Task, executable: 'MAA.exe' | 'MaaEnd.exe', event: Event) { const directory = (event.target as HTMLInputElement).value.trim(); if (directory) void synchronizeExecutable(task, `${directory.replace(/[\\/]+$/, '')}\\${executable}`) }
async function chooseStandalone(target: 'adb' | 'game', task: Task) { const result = await window.desktopRunner?.selectExecutable(null); if (!result?.path) return; if (target === 'adb') ensureMaa(task).adb_executable = result.path; else ensureMaaEnd(task).game_executable = result.path; void save() }
function ensureMaa(task: Task): MAAAdapter { return task.maa_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, adb_executable: null, adb_address: null, last_check_at: null, last_check_ok: null, last_check_message: null } }
function ensureMaaEnd(task: Task): MaaEndAdapter { return task.maaend_adapter ||= { installation_directory: task.executable ? directoryOf(task.executable) : null, game_executable: null, game_arguments: [], game_wait_seconds: 60, close_game_on_finish: true } }
async function checkAdb(task: Task) { const adapter = ensureMaa(task); try { const result = await connection.request('/api/adb-check', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ executable: adapter.adb_executable, address: adapter.adb_address }) }) as { ok: boolean; message: string; checkedAt: string }; adapter.last_check_ok = result.ok; adapter.last_check_message = result.message; adapter.last_check_at = result.checkedAt; notice.value = result.ok ? '安卓模拟器连接检测通过。' : `连接检测未通过：${result.message}；运行时仍会继续启动 MAA GUI。`; void save() } catch (error) { report('连接检测无法完成', error) } }
function updateExecutable(task: Task, event: Event) { void synchronizeExecutable(task, (event.target as HTMLInputElement).value) }
function setText(task: Task, key: 'working_directory' | 'log_path' | 'success_log' | 'failure_log', event: Event) { const value = (event.target as HTMLInputElement).value.trim() || null; const automatic = key === 'success_log' ? task.success_log_rules : key === 'failure_log' ? task.failure_log_rules : []; if (value && automatic.some((rule) => rule.pattern === value)) { notice.value = '自定义规则不能与模板规则重复。'; return }; task[key] = value; void save() }
function setLogPatterns(task: Task, event: Event) { task.log_patterns = (event.target as HTMLInputElement).value.trim() || '*.log;*.txt'; void save() }
function setIdleTimeout(task: Task, event: Event) { const raw = (event.target as HTMLInputElement).value.trim(); task.log_idle_timeout_seconds = raw ? Number(raw) : null; void save() }
async function chooseLogDirectory(task: Task) { const result = await window.desktopRunner?.selectDirectory?.(); if (!result?.path) return; task.log_path = result.path; void save() }
function setArgs(task: Task, event: Event, field: 'arguments' | 'game_arguments' = 'arguments') { const values = ((event.target as HTMLInputElement).value.trim().match(/(?:[^\s"]+|"[^"]*")+/g) || []).map((part) => part.replaceAll('"', '')); if (field === 'arguments') task.arguments = values; else ensureMaaEnd(task).game_arguments = values; void save() }
function useGenericProgram(task: Task) { task.preset_id = null; task.preset_evidence = null; task.maa_adapter = null; task.maaend_adapter = null; delete selectionIssues.value[task.id]; void save() }
async function runScript(script: Queue) { const problems = scriptProblems(script); if (problems.length) { notice.value = problems.join('；'); return } try { await connection.request('/api/start', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ queue_id: script.id }) }); notice.value = `已开始软件脚本“${script.name}”` } catch (error) { report('无法运行脚本', error) } }
async function runAllScripts() { allRunProblems.value = config.value.queues.flatMap(scriptProblems); if (allRunProblems.value.length) { notice.value = '全部脚本尚未完成配置。'; return } try { await connection.request('/api/start-all', { method: 'POST' }); notice.value = '已按软件脚本顺序开始运行。' } catch (error) { report('无法运行全部脚本', error) } }
async function stop() { try { await connection.request('/api/stop', { method: 'POST' }); notice.value = '已请求停止；不会派发下一项。' } catch (error) { report('停止请求未送达', error) } }
async function confirm(taskId: string) { if (confirmationPending.value) return; try { await connection.request('/api/confirm', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ task_id: taskId }) }); confirmationPending.value = true } catch (error) { report('人工确认未被接受', error) } }
async function decideUpdate(taskId: string, action: 'wait' | 'fail' | 'handled' | 'complete') { if (updatePending.value) return; if (action === 'complete' && !window.confirm('确认当前程序的任务已经完成？确认后将结束当前项并继续队列。')) return; updatePending.value = true; try { await connection.request('/api/update-decision', { method: 'POST', headers: { 'content-type': 'application/json' }, body: JSON.stringify({ task_id: taskId, action }) }) } catch (error) { report('更新处理请求未被接受', error) } finally { updatePending.value = false } }
async function cancelCompletionAction() { try { await connection.request('/api/cancel-completion-action', { method: 'POST' }); notice.value = '已取消完成后操作。' } catch (error) { report('无法取消完成后操作', error) } }
function openFailureDetails(runId: string) { selectedHistoryRunId.value = runId; expandedHistory.value = new Set([...expandedHistory.value, runId]); page.value = 'history' }
function openHistoryDetail(runId: string, taskId: string, taskListScrollTop = 0) { selectedHistoryRunId.value = runId; historyDetail.value = { runId, taskId, taskListScrollTop }; historyReturnState.value = historyDetail.value; page.value = 'history-detail' }
function returnHistoryDetail() { historyDetail.value = null; page.value = 'history' }
const reserveRunCenter = computed(() => Boolean(runtime.value.run && (runtime.value.busy || ['delaying', 'countdown', 'executing'].includes(runtime.value.completionAction?.status || ''))))
function toggleHistory(id: string) { const next = new Set(expandedHistory.value); next.has(id) ? next.delete(id) : next.add(id); expandedHistory.value = next }
async function refreshDiagnostics() { backendDetail.value = (await window.desktopRunner?.getBackendStatus?.())?.detail || '' }
async function saveAppSettings(next: AppSettings) {
  if (!window.desktopRunner?.saveSettings) throw new Error('当前运行环境未提供设置保存服务。')
  settingsSaveState.value = 'saving'
  try { appSettings.value = await window.desktopRunner.saveSettings(next); settingsSaveState.value = 'saved' } catch (error) { settingsSaveState.value = 'failed'; throw error }
}
async function exportAppArchive(kind: 'backup' | 'logs' | 'diagnostic', presetId?: string) {
  if (!window.desktopRunner?.exportArchive) throw new Error('当前运行环境未提供导出服务。')
  return await window.desktopRunner.exportArchive({ kind, ...(presetId ? { presetId } : {}) })
}
onMounted(async () => { countdownTimer = window.setInterval(() => { countdownNow.value = Date.now() }, 250); appVersion.value = (await window.desktopRunner?.getBuildInfo?.())?.version || '开发版本不可用'; appSettings.value = await window.desktopRunner?.getSettings?.() || appSettings.value; document.title = `顺序任务调度器 ${appVersion.value}`; await connection.connect(); await refreshDiagnostics(); notice.value = connection.restOnline.value ? '本地后端已就绪。' : '本地后端尚不可用；草稿会保留。' })
onBeforeUnmount(() => { if (countdownTimer) window.clearInterval(countdownTimer); connection.dispose() })
</script>

<template>
  <main class="app"><aside class="side"><div class="brand"><span class="brand-mark" aria-hidden="true">◆</span><b>顺序任务调度器 {{ appVersion }}</b><small>本地软件执行器</small></div><nav><button aria-label="脚本" :class="{ active: page === 'scripts' || page === 'editor' }" @click="navigate('scripts')"><FileCode2 aria-hidden="true" /><span>脚本</span></button><button aria-label="计划" :class="{ active: page === 'schedule' }" @click="navigate('schedule')"><ListChecks aria-hidden="true" /><span>计划</span></button><button aria-label="日志" :class="{ active: page === 'history' || page === 'history-detail' }" @click="navigate('history')"><History aria-hidden="true" /><span>日志</span></button><button aria-label="设置" :class="{ active: page === 'settings' }" @click="navigate('settings')"><Settings aria-hidden="true" /><span>设置</span></button></nav><LiveLog :logs="logs" :runtime="runtime" :script-events="scriptEvents" /></aside>
    <section class="content" :class="{ 'has-reserved-run': reserveRunCenter }">
      <header v-if="page !== 'editor' && page !== 'history-detail'"><div><h1><FileCode2 v-if="page === 'scripts'" aria-hidden="true" /><ListChecks v-else-if="page === 'schedule'" aria-hidden="true" /><History v-else-if="page === 'history'" aria-hidden="true" /><Settings v-else aria-hidden="true" />{{ page === 'scripts' ? '脚本管理' : page === 'schedule' ? '计划管理' : page === 'history' ? '日志' : '设置中心' }}</h1><p>{{ connectionSummary }}</p></div><div class="actions"><span class="connection-chip" :class="{ offline: !connection.restOnline.value }"><Network aria-hidden="true" />API {{ connection.restOnline.value ? '在线' : '离线' }}</span><span class="connection-chip" :class="{ warning: connection.realtimeState.value !== 'online' }"><RefreshCw aria-hidden="true" />{{ connection.realtimeLabel.value }}</span><button class="danger" :disabled="!runtime.busy" @click="stop"><CircleStop aria-hidden="true" />全局停止</button></div></header>
      <RunCenter v-if="page !== 'history-detail'" :runtime="runtime" :countdown="cooldown" :confirmation-pending="confirmationPending" :update-pending="updatePending" @confirm="confirm" @update-decision="decideUpdate" @show-failures="openFailureDetails" @cancel-completion-action="cancelCompletionAction" />
      <div class="content-body">
      <template v-if="page !== 'history-detail'"><p v-if="migrationNotice" class="migration-notice" role="status">{{ migrationNotice }}</p><p v-if="saveError" class="notice" role="alert">{{ saveError }}</p><p class="notice"><span>{{ notice }}</span><span v-if="hasUnsavedDraft" class="draft-state">未保存草稿</span></p></template>
      <section v-if="page === 'scripts'" class="scripts-page"><div class="toolbar"><label class="search-field"><Search aria-hidden="true" /><input v-model="query" placeholder="搜索软件脚本或预设"></label><div><button class="primary" :disabled="runtime.busy" @click="newScript"><Plus aria-hidden="true" />新建脚本</button><button class="run-all" :disabled="runtime.busy || !config.queues.length" @click="runAllScripts"><Play aria-hidden="true" />运行全部脚本</button></div></div><div v-if="allRunProblems.length" class="run-problems"><b><ShieldAlert aria-hidden="true" />无法运行全部脚本</b><ul><li v-for="problem in allRunProblems" :key="problem">{{ problem }}</li></ul></div><p v-if="!visibleScripts.length" class="empty"><FolderOpen aria-hidden="true" /><span>没有软件脚本。新建后直接配置一个软件。</span></p><ScriptCard v-for="script in visibleScripts" :key="script.id" :script="script" :task="scriptTask(script)" :locked="runtime.busy" :blocked="scriptBlocked(script)" :execution="executionFor(script)" :preset-summary="presetSummary(script)" @edit="openEditor(script)" @run="runScript(script)" @duplicate="duplicateScript(script)" @remove="deleteScript(script)" @dragstart="draggedScript = script.id" @drop="moveScript(script.id)" /></section>
      <ScriptEditor v-else-if="page === 'editor' && editingScript && editingTask" :script="editingScript" :task="editingTask" :presets="presets" :busy="runtime.busy" :save-label="editorSaveLabel" :save-state="editorSaveState" :selection-issue="selectionIssues[editingTask.id]" :request="connection.request" :directory-of="directoryOf" :preset-label="presetLabel" :preset-for="presetFor" :preset-rule-text="presetRuleText" :change-preset="changePreset" :choose="choose" :choose-install-directory="chooseInstallDirectory" :update-install-directory="updateInstallDirectory" :update-executable="updateExecutable" :choose-log-directory="chooseLogDirectory" :set-text="setText" :set-log-patterns="setLogPatterns" :set-idle-timeout="setIdleTimeout" :set-args="setArgs" :use-generic-program="useGenericProgram" :choose-standalone="chooseStandalone" :ensure-maa="ensureMaa" :ensure-maa-end="ensureMaaEnd" :check-adb="checkAdb" :save="save" :save-editor-changes="saveEditorChanges" :stop="stop" :close="closeEditor" :remove="deleteScript" />
      <PlanManager v-else-if="page === 'schedule'" :config="config" :selected-plan-id="selectedPlanId" :busy="runtime.busy" @update:selected-plan-id="selectedPlanId = $event" @save="save" />
       <LogPage v-else-if="page === 'history' || page === 'history-detail'" :history="history" :request="connection.request" :selected-id="selectedHistoryRunId" :expanded="expandedHistory" :standalone="page === 'history-detail'" :detail-run-id="historyDetail?.runId || null" :detail-task-id="historyDetail?.taskId || null" :restore-task-id="page === 'history' ? historyReturnState?.taskId || null : null" :restore-task-list-scroll-top="page === 'history' ? historyReturnState?.taskListScrollTop || null : null" @toggle="toggleHistory" @refresh="refreshHistory()" @open-detail="openHistoryDetail" @return-detail="returnHistoryDetail" />
      <SettingsPage v-else :settings="appSettings" :save-state="settingsSaveState" :version="appVersion" :api-online="connection.restOnline.value" :realtime-label="connection.realtimeLabel.value" :diagnostic-text="diagnosticText" :presets="presets" :save-settings="saveAppSettings" :export-archive="exportAppArchive" :refresh-diagnostics="refreshDiagnostics" />
      </div>
    </section></main>
  <div v-if="leaveEditor" class="editor-leave-overlay" @click.self="leaveEditor = false"><section class="editor-leave-dialog" role="alertdialog" aria-modal="true" aria-label="未保存更改"><h2>尚有未保存更改</h2><p>当前编辑只保存在草稿中。请先保存，或明确放弃这些更改。</p><div><button @click="leaveEditor = false">继续编辑</button><button class="danger" @click="finishCloseEditor(leaveDestination)">放弃更改</button><button class="primary" :disabled="editorSaveState === 'saving'" @click="saveEditorChanges">保存并离开</button></div></section></div>
</template>
